class VolumeZMomentum(Strategy):
    name = "volume_z_momentum"
    LOOKBACK = 48
    THRESHOLD = 2.0
    warmup_bars = 50

    def on_bar(self, symbol, store):
        window = store.window(symbol, self.timeframe)
        if len(window) < self.warmup_bars:
            return math.nan
        vols = window.volumes()
        closes = window.closes()
        opens = window.opens()
        vol_z = ta.zscore(vols, self.LOOKBACK)
        if not math.isfinite(vol_z):
            return math.nan
        if vol_z > self.THRESHOLD:
            if closes[-1] > opens[-1]:
                return 1.0
            else:
                return -1.0
        return 0.0
